  function masterMapsUrl(street,house,postal,city){return "https://www.google.com/maps/search/?api=1&query="+encodeURIComponent([street,house,postal,city].filter(Boolean).join(" "))}
  function masterPhone(value){return value?`<a href="tel:${esc(String(value).replace(/[^+\d]/g,''))}">${esc(value)}</a>`:"–"}
  function masterEmail(value){return value?`<a href="mailto:${esc(value)}">${esc(value)}</a>`:"–"}
  function masterExtraRows(rows){return (Array.isArray(rows)?rows:[]).map(row=>`<dt>${esc(row.label||"Zusatz")}</dt><dd>${esc(row.value||"–")}</dd>`).join("")}
